#define MAX_BUFFER_SIZE 1024

// Function to calculate the checksum of a buffer
unsigned int calculateChecksum(const unsigned char *buffer, size_t length) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += buffer[i];
    }
    return checksum;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *inputFileName = argv[1];
    const char *outputFileName = argv[2];

    // Open the input file
    FILE *inputFile = fopen(inputFileName, "rb");
    if (!inputFile) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    // Allocate memory for buffer
    unsigned char *buffer = (unsigned char *)malloc(MAX_BUFFER_SIZE);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(inputFile);
        return EXIT_FAILURE;
    }

    size_t bytesRead = fread(buffer, 1, MAX_BUFFER_SIZE, inputFile);
    fclose(inputFile);

    // Calculate the checksum
    unsigned int checksum = calculateChecksum(buffer, bytesRead);

    // Open the output file
    FILE *outputFile = fopen(outputFileName, "wb");
    if (!outputFile) {
        perror("Failed to open output file");
        free(buffer);
        return EXIT_FAILURE;
    }

    // Write the number of bytes read and the checksum to the output file
    fprintf(outputFile, "%zu %u\n", bytesRead, checksum);

    fclose(outputFile);
    free(buffer);

    return EXIT_SUCCESS;
}
```

