#define BUFFER_SIZE 1024

int main() {
    FILE *inputFile, *outputFile;
    char buffer[BUFFER_SIZE];
    size_t bytesRead = 0;
    unsigned int checksum = 0;

    // Open the input file for reading
    inputFile = fopen("input.txt", "rb");
    if (inputFile == NULL) {
        fprintf(stderr, "Error opening input file.\n");
        return EXIT_FAILURE;
    }

    // Read the contents of the file into a buffer
    bytesRead = fread(buffer, 1, sizeof(buffer), inputFile);
    fclose(inputFile);

    // Calculate the checksum of the buffer
    for (size_t i = 0; i < bytesRead; i++) {
        checksum += buffer[i];
    }

    // Check if the buffer is empty
    int isEmpty = (checksum == 0);

    // Open the output file for writing
    outputFile = fopen("output.txt", "wb");
    if (outputFile == NULL) {
        fprintf(stderr, "Error opening output file.\n");
        return EXIT_FAILURE;
    }

    // Write the number of bytes read and the checksum to the output file
    fwrite(&bytesRead, sizeof(size_t), 1, outputFile);
    fwrite(&checksum, sizeof(unsigned int), 1, outputFile);

    fclose(outputFile);

    printf("Checksum is %u. Buffer is %s.\n", checksum, isEmpty ? "empty" : "not empty");
    printf("Number of bytes read: %zu\n", bytesRead);

    return EXIT_SUCCESS;
}
```

### Explanation:

