```c
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define FILENAME "important_config"
#define INITIAL_CONTENTS "important_config"

int main() {
    int fd;
    const char *contents = INITIAL_CONTENTS;
    ssize_t bytes_written;

    // Open the file with read and write permissions, create if it doesn't exist
    // Set initial permissions: owner (read & write), group (read), others (read)
    fd = open(FILENAME, O_CREAT | O_RDWR, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Write the initial contents to the file
    bytes_written = write(fd, contents, strlen(contents));
    if (bytes_written == -1) {
        perror("write");
        close(fd);
        exit(EXIT_FAILURE);
    }

    printf("Wrote %zd bytes to '%s'\n", bytes_written, FILENAME);

    // Close the file descriptor
    close(fd);

    return 0;
}
```

### Explanation:
1. **`open()` Function**:
   - `O_CREAT | O_RDWR`: This flag combination tells `open()` to create the file if it doesn't exist and open it for both reading and writing.
   - `S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH`: These flags set the permissions for the file:
     - `S_IRUSR` (read permission for the owner)
     - `S_IWUSR` (write permission for the owner)
     - `S_IRGRP` (read permission for the group)
     - `S_IROTH` (read-only permission for others)

2. **`write()` Function**:
