// Function to generate a random float between 0.0 and 1.0
float generateRandomFloat() {
    return (float)rand() / RAND_MAX;
}

int main() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate 3 random floats
    float rand_float1 = generateRandomFloat();
    float rand_float2 = generateRandomFloat();
    float rand_float3 = generateRandomFloat();

    // Convert floats to strings
    char str1[50];
    char str2[50];
    char str3[50];

    snprintf(str1, sizeof(str1), "%.6f", rand_float1);
    snprintf(str2, sizeof(str2), "%.6f", rand_float2);
    snprintf(str3, sizeof(str3), "%.6f", rand_float3);

    // Concatenate the strings
    char result[50 * 3 + 2]; // Assuming each float has at most 50 characters and 1 space between them
    snprintf(result, sizeof(result), "%s %s %s", str1, str2, str3);

    // Write the string to a file
    FILE *file = fopen("output.txt", "w");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    fprintf(file, "%s\n", result);
    fclose(file);

    printf("Random floats written to output.txt: %s\n", result);

    return 0;
}
