        return;
    }

    username_start += strlen("username="); // Move past "username="
    char *newline = strchr(username_start, '\n'); // Find the newline character
    if (newline != NULL) {
        *newline = '\0'; // Null-terminate the username string
    }

    strncpy(username, username_start, sizeof(username) - 1);
    username[sizeof(username) - 1] = '\0'; // Ensure null-termination

    // Construct the response body (HTML page)
