             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "\r\n"
             "<html><head><title>Hello Page</title></head>\n"
             "<body>"
             "<h1>Hello, %s!</h1>"
             "</body></html>",
             username);

    // Write the response body to the response stream
