```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_USERNAME_LENGTH 256

void http_hello_page(FILE *request, FILE *response) {
    char username[MAX_USERNAME_LENGTH];

    // Read the username from the request stream
    if (fgets(username, sizeof(username), request) == NULL) {
        fprintf(stderr, "Error reading username from request.\n");
        return;
    }

    // Remove newline character if present
    size_t len = strlen(username);
    if (len > 0 && username[len - 1] == '\n') {
        username[len - 1] = '\0';
    }

    // Construct the response message
    char *response_message = malloc(256 * sizeof(char));
    if (response_message == NULL) {
        fprintf(stderr, "Memory allocation failed for response message.\n");
        return;
    }

    snprintf(response_message, 256, "Hello %s", username);

    // Write the response to the response stream
    if (fprintf(response, "%s\n", response_message) < 0) {
        fprintf(stderr, "Error writing response to client.\n");
    }

    // Free allocated memory
    free(response_message);
}

int main() {
    // Example usage for testing purposes
    FILE *request = fopen("request.txt", "r"); // Replace with actual request input
    if (request == NULL) {
        perror("Error opening request file");
        return EXIT_FAILURE;
    }

    FILE *response = fopen("response.txt", "w"); // Replace with actual response output
    if (response == NULL) {
        perror("Error opening response file");
        fclose(request);
        return EXIT_FAILURE;
    }

    http_hello_page(request, response);

    fclose(request);
    fclose(response);

    return EXIT_SUCCESS;
}
```

### Explanation:
1. **Reading the Username**: The function reads a line from the `request` stream using `fgets`, which also handles the newline character.
2. **Constructing the Response**: A buffer is allocated to hold the response message, and `snprintf` is used to construct it safely.
3. **Writing the Response**: The constructed response is written to the `response` stream using `fprintf`.
4. **Memory Management**: Dynamically allocated memory for the response message is freed to prevent memory leaks.

### Notes:
- Replace `"request.txt"` and `"response.txt"` with actual file paths or methods to read from and write to the client's request and response streams.
- Error handling is basic, but you can expand it as needed based on your requirements.']

